(function(){
  if (window.Soundfont) return;

  function getNonce(){
    // Prefer explicit meta, else inherit from the current script if present
    var m = document.querySelector('meta[name="csp-nonce"]');
    if (m && m.content) return m.content;
    try{ var cs = document.currentScript; if (cs && cs.nonce) return cs.nonce; }catch(e){}
    return null;
  }

  function loadScript(url){
    return new Promise(function(resolve, reject){
      var s=document.createElement('script'); s.src=url; s.async=true; s.crossOrigin='anonymous';
      var n = getNonce(); if (n) s.setAttribute('nonce', n);
      s.onload=function(){ resolve(); }; s.onerror=function(e){ reject(e); };
      document.head.appendChild(s);
    });
  }

  function midiToName(m){
    var NOTES=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
    var n=NOTES[m%12], o=Math.floor(m/12)-1;
    return n+o;
  }
  function parseNote(name){
    var m=name.match(/^([A-G])(#|b)?(-?\d+)$/);
    if(!m) return 60;
    var base={'C':0,'D':2,'E':4,'F':5,'G':7,'A':9,'B':11}[m[1]];
    var alt=(m[2]==='#')?1:((m[2]==='b')?-1:0);
    var oct=parseInt(m[3],10);
    return (oct+1)*12 + base + alt;
  }
  function nearestSample(midi, available){
    var best=null, bestDist=1e9;
    for (var i=0;i<available.length;i++){
      var nm=available[i]; var p=parseNote(nm);
      var d=Math.abs(p - midi);
      if (d<bestDist){ best=nm; bestDist=d; }
    }
    return best||available[0];
  }
  function createPlayer(ctx, mapping, destination){
    destination = destination || ctx.destination;
    return {
      play: function(midi, when, params){
        when = (when||0);
        var keys = Object.keys(mapping);
        if (keys.length===0) return { stop:function(){} };
        var prefer = midiToName(midi);
        var name = keys.indexOf(prefer)>=0 ? prefer : nearestSample(midi, keys);
        var url = mapping[name];
        var el = new Audio();
        el.src = url; el.preload='auto'; el.crossOrigin='anonymous';
        var node=null;
        try{ node = ctx.createMediaElementSource(el); node.connect(destination); }catch(e){}
        el.volume = (params && params.gain!=null)? Math.max(0,Math.min(1,params.gain)) : 1.0;
        setTimeout(function(){ try{ el.currentTime=0; el.play(); }catch(e){} }, Math.max(0, when*1000));
        return { stop: function(){ try{ el.pause(); el.currentTime=0; }catch(e){} try{ if(node) node.disconnect(); }catch(e){} } };
      }
    };
  }

  function defaultNameToUrl(name, soundfont, format){
    var base = (typeof window.EFK_SF_BASE==='string' && window.EFK_SF_BASE.length)
      ? window.EFK_SF_BASE.replace(/\/+$/,'')
      : ((document.body && document.body.getAttribute('data-sf-base')) || '/soundfonts').replace(/\/+$/,'');
    var url = base + '/' + (soundfont||'MusyngKite') + '/' + name + '-' + (format||'mp3') + '.js';
    console.log('[SoundFont shim] loading', url);
    return url;
  }

  if (!window.MIDI) window.MIDI = {};
  if (!window.MIDI.Soundfont) window.MIDI.Soundfont = {};

  window.Soundfont = {
    instrument: function(ctx, name, opts){
      opts = opts || {};
      var sf = opts.soundfont || 'MusyngKite';
      var fmt = opts.format || 'mp3';
      var n2u = opts.nameToUrl || defaultNameToUrl;
      var url = n2u(name, sf, fmt);
      return new Promise(function(resolve, reject){
        if (window.MIDI.Soundfont[name]){
          return resolve(createPlayer(ctx, window.MIDI.Soundfont[name], opts.destination));
        }
        loadScript(url).then(function(){
          if (!window.MIDI.Soundfont[name]){
            return reject(new Error('Instrument mapping "'+name+'" not found after loading '+url));
          }
          resolve(createPlayer(ctx, window.MIDI.Soundfont[name], opts.destination));
        }).catch(function(e){ reject(e); });
      });
    }
  };
})();